// Integration test against the REAL ffmpeg.wasm core (@ffmpeg/core 0.12.10, the exact bytes served from /vendor/ffmpeg).
// Nothing is mocked: capabilities are probed from the core's own `-encoders/-muxers/...` output, every command comes
// from the production buildArgs(), runs on synthetic media generated by ffmpeg itself, and every output is checked
// with magic bytes AND the core's ffprobe.
import { beforeAll, describe, expect, it } from "vitest";
import type { MediaCaps } from "../caps";
import {
  LEVELS,
  SPEEDS,
  audioInputsFor,
  audioTargetsFor,
  buildArgs,
  supportsOp,
  videoInputsFor,
  videoTargetsFor,
} from "../lib/ffmpeg-args";
import { CORE_VERSION, buildMediaCaps, classifyFfmpegLog } from "../lib/ffmpeg-probe";
import { RealCore, magicOf, type MediaInfo } from "./media-core-node";

let core: RealCore | null = null;
let skipReason = "";
try {
  core = await RealCore.load();
} catch (e) {
  skipReason = e instanceof Error ? e.message : String(e);
  console.warn(`[media-ffmpeg-real] SKIPPED: the real ffmpeg core could not be loaded in Node: ${skipReason}`);
}
const real = describe.skipIf(!core);

function listing(kind: string): string {
  return core!.run(["-hide_banner", `-${kind}`]).log.join("\n");
}

const NO_CAPS = { encoders: [], decoders: [], muxers: [], demuxers: [], filters: [], coreVersion: "" } as MediaCaps;
const caps: MediaCaps | null = core
  ? buildMediaCaps(CORE_VERSION, {
      encoders: listing("encoders"),
      decoders: listing("decoders"),
      muxers: listing("muxers"),
      demuxers: listing("demuxers"),
      filters: listing("filters"),
    })
  : null;
const C = caps ?? NO_CAPS;
const AUDIO_IN = audioInputsFor(C);
const AUDIO_OUT = audioTargetsFor(C);
const VIDEO_IN = videoInputsFor(C);
const VIDEO_OUT = videoTargetsFor(C);

async function gen(args: string[], out: string): Promise<Uint8Array> {
  await core!.begin();
  const r = core!.run(args);
  const bytes = core!.read(out);
  if (r.code !== 0 || !bytes) throw new Error(`fixture ${out} failed: ${r.log.slice(-4).join(" | ")}`);
  core!.remove(out);
  return bytes;
}

interface Result {
  code: number;
  log: string[];
  out: Uint8Array | null;
  info: MediaInfo | null;
  outExt: string;
  mime: string;
}

/** Runs one production command exactly like media.impl does: in0.<ext> in, out.<ext> out. */
async function exec(op: string, src: Uint8Array, ext: string, options: Record<string, string | number | boolean> = {}): Promise<Result> {
  const built = buildArgs(op, ext, options, caps!);
  await core!.begin();
  core!.remove(built.outputName); // never read a stale output from an earlier command
  core!.write(built.inputName, src);
  const r = core!.run(built.args);
  const out = r.code === 0 ? core!.read(built.outputName) : null;
  const usable = out && out.length > 0 ? out : null;
  const info = usable ? core!.info(built.outputName) : null;
  core!.remove(built.inputName);
  core!.remove(built.outputName);
  return { code: r.code, log: r.log, out: usable, info, outExt: built.outputExt, mime: built.mime };
}

function good(res: Result, ext: string): { out: Uint8Array; info: MediaInfo } {
  expect(res.code, res.log.slice(-4).join(" | ")).toBe(0);
  expect(res.out, "no output").not.toBeNull();
  expect(res.out!.length).toBeGreaterThan(100);
  expect(magicOf(ext, res.out!), `${ext} magic bytes`).toBe(true);
  expect(res.info).not.toBeNull();
  return { out: res.out!, info: res.info! };
}

const SINE = ["-f", "lavfi", "-i", "sine=frequency=440:duration=1"];
const EVEN = "scale=trunc(iw/2)*2:trunc(ih/2)*2";

real("probe of the real core", () => {
  it("reports exactly which audio/video formats this core supports", () => {
    console.log(
      [
        `core ${CORE_VERSION}`,
        `audio inputs : ${AUDIO_IN.join(",")}`,
        `audio targets: ${AUDIO_OUT.join(",")}`,
        `video inputs : ${VIDEO_IN.join(",")}`,
        `video targets: ${VIDEO_OUT.join(",")}`,
      ].join("\n"),
    );
    expect(C.encoders.length).toBeGreaterThan(100);
    expect(C.decoders.length).toBeGreaterThan(200);
    expect(C.muxers.length).toBeGreaterThan(100);
    expect(C.demuxers.length).toBeGreaterThan(200);
    expect(C.filters.length).toBeGreaterThan(200);
  });

  it("supports every catalog audio format as input and output", () => {
    expect([...AUDIO_IN].sort()).toEqual(["aac", "aiff", "flac", "m4a", "mp3", "ogg", "opus", "wav", "wma"]);
    expect([...AUDIO_OUT].sort()).toEqual(["aac", "aiff", "flac", "m4a", "mp3", "ogg", "opus", "wav", "wma"]);
  });

  it("supports every catalog video format as input and the web video targets as output", () => {
    expect([...VIDEO_IN].sort()).toEqual(["avi", "flv", "gif", "m4v", "mkv", "mov", "mp4", "webm", "wmv"]);
    expect([...VIDEO_OUT].sort()).toEqual(["avi", "gif", "mkv", "mov", "mp4", "webm", "wmv"]);
  });
});

real("audio: every input -> every other target, plus audio tools", () => {
  const sources = new Map<string, Uint8Array>();
  beforeAll(async () => {
    const wav = await gen([...SINE, "-c:a", "pcm_s16le", "src.wav"], "src.wav");
    sources.set("wav", wav);
    for (const t of AUDIO_OUT) {
      if (t === "wav") continue;
      sources.set(t, good(await exec(`convert:${t}`, wav, "wav"), t).out);
    }
  });

  const pairs = AUDIO_IN.flatMap((i) => AUDIO_OUT.filter((t) => t !== i).map((t) => [i, t] as const));
  it.each(pairs)("%s -> %s", async (from, to) => {
    const { info } = good(await exec(`convert:${to}`, sources.get(from)!, from), to);
    expect(info.hasAudio).toBe(true);
    expect(info.hasVideo).toBe(false);
    expect(info.duration).toBeGreaterThan(0.85);
    expect(info.duration).toBeLessThan(1.25);
  });

  it.each(AUDIO_IN)("aud.normalize keeps format and duration, 48 kHz (%s)", async (ext) => {
    const { info } = good(await exec("aud.normalize", sources.get(ext)!, ext), ext);
    expect(info.hasAudio).toBe(true);
    expect(info.duration).toBeGreaterThan(0.85);
    expect(info.duration).toBeLessThan(1.3);
    expect(info.streams.find((s) => s.type === "audio")!.sampleRate).toBe(48000);
  });

  it.each(AUDIO_IN)("aud.trim 0.25 -> 0.75 gives ~0.5 s (%s)", async (ext) => {
    const { info } = good(await exec("aud.trim", sources.get(ext)!, ext, { start: "0.25", end: "0.75" }), ext);
    expect(info.duration).toBeGreaterThan(0.38);
    expect(info.duration).toBeLessThan(0.65);
  });

  it("aud.trim with only a start (decimal comma, Arabic-Indic digits) runs to the end", async () => {
    const a = good(await exec("aud.trim", sources.get("wav")!, "wav", { start: "0,5", end: "" }), "wav");
    expect(a.info.duration).toBeGreaterThan(0.4);
    expect(a.info.duration).toBeLessThan(0.6);
    const b = good(await exec("aud.trim", sources.get("wav")!, "wav", { start: "٠٫٢٥", end: "٠:٠٠٫٧٥" }), "wav");
    expect(b.info.duration).toBeGreaterThan(0.4);
    expect(b.info.duration).toBeLessThan(0.6);
  });

  it("garbage input fails with decodeFailed", async () => {
    const junk = new Uint8Array(4096).map((_, i) => (i * 131 + 7) & 0xff);
    const res = await exec("convert:wav", junk, "mp3");
    expect(res.code).not.toBe(0);
    expect(classifyFfmpegLog(res.log)).toBe("decodeFailed");
  });
});

real("video: conversion, tools, failure handling", () => {
  let mp4Av: Uint8Array;
  let mp4Silent: Uint8Array;
  let oddAvi: Uint8Array;
  const sources = new Map<string, Uint8Array>();

  beforeAll(async () => {
    mp4Av = await gen(
      [
        "-f", "lavfi", "-i", "testsrc=duration=2:size=96x64:rate=10",
        "-f", "lavfi", "-i", "sine=frequency=440:duration=2",
        "-c:v", "libx264", "-pix_fmt", "yuv420p", "-c:a", "aac", "-shortest", "src.mp4",
      ],
      "src.mp4",
    );
    mp4Silent = await gen(["-f", "lavfi", "-i", "testsrc=duration=2:size=96x64:rate=10", "-c:v", "libx264", "-pix_fmt", "yuv420p", "silent.mp4"], "silent.mp4");
    oddAvi = await gen(["-f", "lavfi", "-i", "testsrc=duration=2:size=97x65:rate=10", "-c:v", "mjpeg", "odd.avi"], "odd.avi");
    sources.set("mp4", mp4Av);
    sources.set("m4v", mp4Av); // same bytes; ffmpeg sniffs the content, the extension only names the file
    sources.set(
      "flv",
      await gen(
        [
          "-f", "lavfi", "-i", "testsrc=duration=2:size=96x64:rate=10",
          "-f", "lavfi", "-i", "sine=duration=2",
          "-vf", EVEN, "-c:v", "flv", "-c:a", "libmp3lame", "-ar", "44100", "-shortest", "-f", "flv", "src.flv",
        ],
        "src.flv",
      ),
    );
    for (const t of VIDEO_OUT) {
      if (t === "mp4") continue;
      sources.set(t, good(await exec(`convert:${t}`, mp4Av, "mp4"), t).out);
    }
  });

  const FROM_MP4 = VIDEO_OUT.filter((t) => t !== "mp4"); // mp4 -> mp4 is never offered
  it.each(FROM_MP4)("mp4 (with audio) -> %s", async (t) => {
    const res = await exec(`convert:${t}`, mp4Av, "mp4");
    const { info } = good(res, t);
    expect(info.hasVideo).toBe(true);
    expect(info.hasAudio).toBe(t !== "gif");
    expect(info.duration).toBeGreaterThan(1.7);
    expect(info.duration).toBeLessThan(2.5);
  });

  it.each(FROM_MP4)("mp4 WITHOUT audio -> %s (no failure)", async (t) => {
    const { info } = good(await exec(`convert:${t}`, mp4Silent, "mp4"), t);
    expect(info.hasVideo).toBe(true);
    expect(info.hasAudio).toBe(false);
  });

  it.each(VIDEO_IN.filter((e) => e !== "mp4"))("%s input -> mp4", async (ext) => {
    const { info } = good(await exec("convert:mp4", sources.get(ext)!, ext), "mp4");
    expect(info.hasVideo).toBe(true);
    expect(info.streams.find((s) => s.type === "video")!.codec).toBe("h264");
  });

  it.each(AUDIO_OUT)("video -> %s (audio extraction)", async (t) => {
    const { info } = good(await exec(`convert:${t}`, mp4Av, "mp4"), t);
    expect(info.hasAudio).toBe(true);
    expect(info.hasVideo).toBe(false);
    expect(info.duration).toBeGreaterThan(1.7);
  });

  it.each(["mkv", "mov", "webm", "avi", "wmv", "flv", "m4v"])("extracts audio from a %s", async (ext) => {
    const { info } = good(await exec("convert:mp3", sources.get(ext)!, ext), "mp3");
    expect(info.hasVideo).toBe(false);
    expect(info.hasAudio).toBe(true);
  });

  it("odd-sized input (97x65) still encodes: the even-dimension scale rounds down to 96x64", async () => {
    for (const t of ["mp4", "mkv", "mov", "webm", "wmv"]) {
      const { info } = good(await exec(`convert:${t}`, oddAvi, "avi"), t);
      const v = info.streams.find((s) => s.type === "video")!;
      expect([v.width, v.height], t).toEqual([96, 64]);
    }
    expect(supportsOp("convert:avi", "avi", C)).toBe(false);
  });

  it("a gif input converts to mp4", async () => {
    const { info } = good(await exec("convert:mp4", sources.get("gif")!, "gif"), "mp4");
    expect(info.hasAudio).toBe(false);
  });

  it("audio extraction from a silent video fails cleanly (noAudio) and the core keeps working", async () => {
    const res = await exec("convert:mp3", mp4Silent, "mp4");
    expect(res.code).not.toBe(0);
    expect(res.out).toBeNull();
    expect(classifyFfmpegLog(res.log)).toBe("noAudio");
    good(await exec("convert:mp3", mp4Av, "mp4"), "mp3");
  });

  // ------------------------------------------------------------------ tools
  const editExts = ["mp4", "m4v", "mov", "mkv", "webm", "avi"];

  it.each(editExts)("vid.trim 0.5 -> 0:01.5 gives ~1 s (%s)", async (ext) => {
    const { info } = good(await exec("vid.trim", sources.get(ext)!, ext, { start: "0.5", end: "0:01.5" }), ext === "m4v" ? "mp4" : ext);
    expect(info.hasVideo).toBe(true);
    expect(info.duration).toBeGreaterThan(0.8);
    expect(info.duration).toBeLessThan(1.3);
  });

  it("vid.trim on a silent video works and stays silent", async () => {
    const { info } = good(await exec("vid.trim", mp4Silent, "mp4", { start: "0", end: "1" }), "mp4");
    expect(info.hasAudio).toBe(false);
    expect(info.duration).toBeGreaterThan(0.8);
    expect(info.duration).toBeLessThan(1.3);
  });

  it.each(["mp4", "m4v", "mov", "mkv", "webm", "avi", "wmv", "flv"])("vid.mute drops audio, keeps video, no re-encode (%s)", async (ext) => {
    const { info } = good(await exec("vid.mute", sources.get(ext)!, ext), ext === "m4v" ? "mp4" : ext);
    expect(info.hasAudio, "audio left").toBe(false);
    expect(info.hasVideo).toBe(true);
    expect(info.duration).toBeGreaterThan(1.7);
  });

  it.each(["mp4", "mkv", "webm", "avi", "wmv", "flv", "gif", "mov"])("vid.snapshot at 1 s is a PNG of the right size (%s)", async (ext) => {
    const { info } = good(await exec("vid.snapshot", sources.get(ext)!, ext, { time: "1" }), "png");
    const v = info.streams.find((s) => s.type === "video")!;
    expect(v.codec).toBe("png");
    expect([v.width, v.height]).toEqual([96, 64]);
  });

  it("vid.snapshot past the end produces no frame (the UI reports noFrame)", async () => {
    const res = await exec("vid.snapshot", mp4Av, "mp4", { time: "99" });
    expect(res.out).toBeNull();
  });

  it.each(SPEEDS.map((s) => [s]))("vid.speed x%s changes the duration accordingly (mp4 with audio)", async (speed) => {
    const { info } = good(await exec("vid.speed", mp4Av, "mp4", { speed }), "mp4");
    expect(info.hasAudio).toBe(true);
    expect(Math.abs(info.duration - 2 / Number(speed))).toBeLessThan(0.4);
  });

  it("vid.speed works without an audio track, and on webm/avi/mkv/mov", async () => {
    const silent = good(await exec("vid.speed", mp4Silent, "mp4", { speed: "4" }), "mp4");
    expect(silent.info.hasAudio).toBe(false);
    expect(Math.abs(silent.info.duration - 0.5)).toBeLessThan(0.4);
    for (const ext of ["webm", "avi", "mkv", "mov"]) {
      const { info } = good(await exec("vid.speed", sources.get(ext)!, ext, { speed: "2" }), ext);
      expect(Math.abs(info.duration - 1)).toBeLessThan(0.4);
    }
  });

  it("vid.compress: every level yields a valid file and the smallest is smaller than a high-quality source", async () => {
    const big = await gen(
      ["-f", "lavfi", "-i", "testsrc2=duration=2:size=320x240:rate=15", "-f", "lavfi", "-i", "sine=duration=2", "-c:v", "libx264", "-crf", "8", "-pix_fmt", "yuv420p", "-c:a", "aac", "-b:a", "256k", "-shortest", "big.mp4"],
      "big.mp4",
    );
    const srcs: [string, Uint8Array][] = [
      ["mp4", big],
      ["webm", good(await exec("convert:webm", big, "mp4"), "webm").out],
      ["avi", good(await exec("convert:avi", big, "mp4"), "avi").out],
      ["mkv", good(await exec("convert:mkv", big, "mp4"), "mkv").out],
    ];
    for (const [ext, src] of srcs) {
      const sizes: number[] = [];
      for (const level of LEVELS) {
        const { out, info } = good(await exec("vid.compress", src, ext, { level }), ext);
        expect(info.hasVideo).toBe(true);
        expect(info.hasAudio).toBe(true);
        sizes.push(out.length);
      }
      expect(Math.min(...sizes), `${ext} should shrink`).toBeLessThan(src.length);
      expect(sizes[2], `${ext}: small <= high`).toBeLessThanOrEqual(sizes[0]);
    }
  });

  it("vid.compress caps the width at 1280 for medium/small but keeps it for high", async () => {
    const wide = await gen(["-f", "lavfi", "-i", "testsrc=duration=1:size=1600x900:rate=3", "-c:v", "libx264", "-pix_fmt", "yuv420p", "wide.mp4"], "wide.mp4");
    const mv = good(await exec("vid.compress", wide, "mp4", { level: "medium" }), "mp4").info.streams.find((s) => s.type === "video")!;
    expect([mv.width, mv.height]).toEqual([1280, 720]);
    const hv = good(await exec("vid.compress", wide, "mp4", { level: "high" }), "mp4").info.streams.find((s) => s.type === "video")!;
    expect([hv.width, hv.height]).toEqual([1600, 900]);
  });

  it("ffmpeg reports progress as fractions in [0, 1] when it knows the duration", async () => {
    const built = buildArgs("vid.compress", "mp4", { level: "medium" }, caps!);
    await core!.begin();
    core!.write(built.inputName, mp4Av);
    const r = core!.run(built.args);
    expect(r.code).toBe(0);
    const sane = r.progress.filter((p) => p.progress >= 0 && p.progress <= 1);
    expect(sane.length).toBeGreaterThan(0);
  });
});

describe("real core availability", () => {
  it(core ? "the real ffmpeg core loaded in Node" : `SKIPPED (visible): ${skipReason}`, () => {
    if (!core) {
      expect(skipReason.length).toBeGreaterThan(0);
      return;
    }
    expect(caps).not.toBeNull();
    expect(core.recycles).toBeGreaterThanOrEqual(0);
  });
});
